## 3. Middleware de Autorización

```javascript
// stock-controll-back/middlewares/rbacMiddleware.js
const rbacService = require('../services/rbacService');

/**
 * Middleware RBAC que verifica permisos atómicos
 * @param {string} permission - Permiso requerido (ej: "product.create")
 */
const requirePermission = (permission) => {
  return async (req, res, next) => {
    try {
      const userId = req.user?.id;
      const storeId = req.headers['x-store-id'] || req.user?.storeId;

      if (!userId) {
        return res.status(401).json({ error: 'UNAUTHORIZED', message: 'Usuario no autenticado' });
      }

      const hasPermission = await rbacService.checkPermission({
        userId,
        storeId,
        permission
      });

      if (!hasPermission) {
        // Log de acceso denegado (para auditoría)
        console.warn(`[RBAC] DENIED: User ${userId} lacks "${permission}" for store ${storeId}`);

        return res.status(403).json({ 
          error: 'FORBIDDEN', 
          message: `Missing permission: ${permission}`,
          required: permission
        });
      }

      next();
    } catch (error) {
      console.error(`[RBAC] Error: ${error.message}`);
      return res.status(500).json({ error: 'INTERNAL_ERROR', message: 'Error en verificación de permisos' });
    }
  };
};

module.exports = { requirePermission };
```

---

## 4. Servicio de Autorización

```javascript
// stock-controll-back/services/rbacService.js
const prisma = require('../db/database.prisma');
const permissionsCache = require('./permissionsCache');

const RBAC_SERVICE = {
  /**
   * Verifica si usuario tiene permiso específico
   */
  async checkPermission({ userId, storeId, permission }) {
    // 1. Obtener usuario con su rol y permisos
    const user = await prisma.user.findUnique({
      where: { id: userId },
      include: {
        role: {
          include: {
            permissions: {
              include: { permission: true }
            }
          }
        }
      }
    });

    if (!user || !user.isActive) {
      return false;
    }

    // 2. SISTEMA: acceso total previa validación de store
    if (user.role.name === 'SISTEMA') {
      if (!storeId) return false;
      const storeExists = await prisma.store.findUnique({ where: { id: storeId } });
      return !!storeExists;
    }

    // 3. Validar store context para otros roles
    if (storeId && user.storeId !== storeId) {
      // ADMIN/ENCARGADO/VENDEDOR solo pueden operar en su tienda
      return false;
    }

    // 4. Verificar permiso específico
    const userPermissions = user.role.permissions.map(p => p.permission.name);
    return userPermissions.includes(permission);
  },

  /**
   * Obtiene todos los permisos del usuario (para UI)
   */
  async getUserPermissions(userId) {
    const cacheKey = `user_permissions_${userId}`;

    // Check cache first
    const cached = permissionsCache.get(cacheKey);
    if (cached) return cached;

    const user = await prisma.user.findUnique({
      where: { id: userId },
      include: {
        role: {
          include: {
            permissions: {
              include: { permission: true }
            }
          }
        }
      }
    });

    if (!user) return [];

    const permissions = user.role.permissions.map(p => p.permission.name);

    // Cache for 5 minutes
    permissionsCache.set(cacheKey, permissions, 300000);

    return permissions;
  },

  /**
   * Asigna rol a usuario (con validación)
   */
  async assignRole({ targetUserId, newRoleId, assignedByUserId }) {
    // Verificar que el asignador tiene permiso user.manage-roles
    const canAssign = await this.checkPermission({
      userId: assignedByUserId,
      storeId: null, // Validar después con el contexto
      permission: 'user.manage-roles'
    });

    if (!canAssign) {
      throw new Error('No tienes permiso para asignar roles');
    }

    await prisma.user.update({
      where: { id: targetUserId },
      data: { roleId: newRoleId }
    });

    // Invalidate cache
    permissionsCache.invalidate(`user_permissions_${targetUserId}`);
  }
};

module.exports = RBAC_SERVICE;
```

### Cache de Permisos

```javascript
// stock-controll-back/services/permissionsCache.js
class PermissionsCache {
  constructor() {
    this.cache = new Map();
  }

  get(key) {
    const entry = this.cache.get(key);
    if (!entry) return null;

    if (Date.now() > entry.expiresAt) {
      this.cache.delete(key);
      return null;
    }

    return entry.value;
  }

  set(key, value, ttlMs = 300000) {
    this.cache.set(key, {
      value,
      expiresAt: Date.now() + ttlMs
    });
  }

  invalidate(key) {
    this.cache.delete(key);
  }

  invalidatePattern(pattern) {
    for (const key of this.cache.keys()) {
      if (key.includes(pattern)) {
        this.cache.delete(key);
      }
    }
  }

  clear() {
    this.cache.clear();
  }
}

module.exports = new PermissionsCache();
```

