async function migrateUsers() {
  // Mapear roles old -> new
  const roleMapping = {
    'SUPERADMIN': 'SISTEMA',
    'ADMIN': 'ADMINISTRADOR',
    'USUARIO': 'VENDEDOR' // Default para usuarios regulares
